cd /tmp/llm-super-agent/phoenix-ledger && echo "=== Check traffic log for any non-2xx ===" && python3 -c "
import json
non_2xx = []
seqs = []
with open('traffic.log') as f:
    for line in f:
        if line.strip():
            e = json.loads(line)
            seqs.append(e['seq'])
            if e['status'] < 200 or e['status'] >= 300:
                non_2xx.append(e)
print(f'Total traffic events: {len(seqs)}')
print(f'Non-2xx: {len(non_2xx)}')
if non_2xx:
    for e in non_2xx[:5]:
        print(json.dumps(e))
expected = list(range(1, len(seqs)+1))
gaps = []
for i, (a, b) in enumerate(zip(seqs, expected)):
    if a != b:
        gaps.append((i, a, b))
print(f'Sequence gaps: {len(gaps)}')
if gaps:
    for g in gaps[:5]:
        print(g)
"

